import {validateMembers,mergeMembers,attendance} from './attendance.js';
import {STATES,esc,hours,category,validateRecord,validateImport,assertNoOverlap,bounds,selectRecords,summarize,dailyMinutes,makeDemo} from './model.js';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function uuid(){if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;return [...b].map((v,i)=>([4,6,8,10].includes(i)?'-':'')+v.toString(16).padStart(2,'0')).join('')}
const KEY='vicio.records.v1',MODE='vicio.mode.v1';
let members=[],local=[],mode='real',remote=false,remoteState=null,view='resumen',period='month',page=1,search='',selected=[],summary,range,toastTimer;
let storageOK=true,storageIssue='',localBackup=null;
try{const raw=localStorage.getItem(KEY);if(raw){const payload=JSON.parse(raw);local=validateImport(payload);members=validateMembers(payload.members||[]);}}catch(e){storageOK=false;storageIssue='No se pudo leer el historial local: '+e.message}
const demo=makeDemo().filter(r=>!(r.userId==='gago'&&Date.parse(r.start)>Date.now()-17*86400000)&&!(r.userId==='lucas'&&Date.parse(r.start)>Date.now()-45*86400000)).map(r=>r.userId==='nico'?{...r,inVoice:false,spoke:'unknown',channel:'',muted:false,streaming:false}:r);
const demoMembers=[...mergeMembers([],demo),{id:'toti',name:'Toti',since:new Date(Date.now()-90*86400000).toISOString(),active:true}];
const titles={resumen:['¿Quién se hace el sota?','El radar de los que aparecen, los que miran de lejos y los que se borran.'],banda:['La banda, bajo la lupa','Cada uno tiene su estilo. El archivo tiene las pruebas.'],juegos:['Acá se fueron las horas','Los mundos que visitamos y quién se sumó a cada partida.'],historial:['Todo queda en el archivo','De «entro cinco minutos» a «¿ya está amaneciendo?».'],ajustes:['La sala de máquinas','Tus registros, tus respaldos y el próximo paso: Discord.']};
const colors=['#d7e5b3','#e6d6bd','#cadacf','#dcd3e3','#e6d1bc','#d2ddbb','#c7dcd9','#dfdcbf'];
const weekdays=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
function initials(s){return s.trim().split(/\s+/).map(x=>Array.from(x)[0]).slice(0,2).join('').toUpperCase()}
function avatar(name,id=''){const hash=[...id+name].reduce((s,c)=>s+c.charCodeAt(0),0);return `<span class="avatar" style="background:${colors[hash%colors.length]}">${esc(initials(name))}</span>`}
function date(d,opts={}){return new Date(d).toLocaleDateString('es-AR',{day:'2-digit',month:'short',...opts})}
function time(d){return new Date(d).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}
function currentMembers(){return mode==='demo'?demoMembers:mergeMembers(members,local)}
function radarRows(){return attendance(current(),currentMembers(),range[0],range[1]).filter(m=>!$('#player-filter').value||m.id===$('#player-filter').value)}
function current(){return mode==='demo'?demo:local}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500)}
function saveLocal(){try{localStorage.setItem(KEY,JSON.stringify({version:1,records:local,members:mergeMembers(members,local)}));localStorage.setItem(MODE,mode);storageOK=true;return true}catch(e){storageOK=false;toast('No se pudo guardar en este navegador. Exportá un respaldo antes de cerrar.');return false}}
function persistMode(){try{localStorage.setItem(MODE,mode)}catch{}}
function stateBadge(r){const key=category(r);return `<span class="state-badge" style="--badge:${STATES[key].color}">${STATES[key].label}</span>`}
function plural(n,one,many){return n+' '+(n===1?one:many)}
function percent(n,d){return d?Math.round(n/d*100):0}
function microbar(groups,total){return `<div class="microbar">${Object.entries(groups).filter(([,m])=>m>0).map(([k,m])=>`<span style="width:${m/total*100}%;background:${STATES[k].color}" title="${STATES[k].label}: ${hours(m)} h"></span>`).join('')}</div>`}
function periodRange(){const a=$('#range-start').value,b=$('#range-end').value;return bounds(period==='custom'&&(!a||!b||a>b)?'month':period,new Date(),{start:a,end:b})}
function populateFilters(){
 const data=current(),members=new Map(currentMembers().map(m=>[m.id,m.name])),games=new Set();data.forEach(r=>{if(r.game)games.add(r.game)});
 const opts=(s,items,first)=>{const el=$(s),value=el.value;el.innerHTML=`<option value="">${first}</option>`+items.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('');if(items.some(([v])=>v===value))el.value=value};
 opts('#player-filter',[...members].sort((a,b)=>a[1].localeCompare(b[1])),'Toda la banda');opts('#game-filter',[...games].sort().map(g=>[g,g]),'Todos los juegos');opts('#state-filter',Object.entries(STATES).map(([k,v])=>[k,v.label]),'Todas las actividades');
 $('#member-names').innerHTML=[...members.values()].map(n=>`<option value="${esc(n)}">`).join('');$('#game-names').innerHTML=[...games].map(n=>`<option value="${esc(n)}">`).join('');
}
function render(){
 range=periodRange();selected=selectRecords(current(),{start:range[0],end:range[1],user:$('#player-filter').value,game:$('#game-filter').value,state:$('#state-filter').value,search,extras:Object.fromEntries($$('[data-extra]').map(el=>[el.dataset.extra,el.value]))});summary=summarize(selected);
 $('#date-line').textContent=`${date(range[0],{year:'numeric'})} — ${date(range[1],{year:'numeric'})}`;
 $('#record-count').textContent=`${plural(selected.length,'TRAMO','TRAMOS')}`;
 $('#data-label').textContent=mode==='demo'?'DATOS DE MUESTRA':remote?'DATOS DEL SERVIDOR':'MIS DATOS · LOCAL';$('#data-label').classList.toggle('real',mode!=='demo');
 $('#toggle-data').textContent=mode==='demo'?(remote?'Volver a Discord ↗':'Ver mis datos ↗'):'Ver muestra ficticia ↗';
 const warnings=[];if(mode==='demo')warnings.push('MUESTRA FICTICIA · Explorá el tablero. Tus datos reales se guardan por separado.');else warnings.push(remote?'DISCORD · Integrantes reconocidos automáticamente. El historial se guarda en la base de datos.':'REGISTRO LOCAL · Guardado en este navegador. Exportá respaldos para conservarlo o moverlo.');
 if(localBackup&&mode!=='demo')warnings.push('Tenés un respaldo local pendiente de migrar en Datos e integración.');
 if(!storageOK)warnings.push(storageIssue||'El navegador no pudo guardar los cambios. Exportá tu respaldo.');
 $('#mode-notice').textContent=warnings.join(' ');
 $('#content').innerHTML=({resumen:overview,banda:playersView,juegos:gamesView,historial:historyView,ajustes:settingsView}[view])();
}
const attendanceLabels={never:'Sin estrenar',missing:'No apareció',away:'Hace rato que no viene',lurker:'Online, sin voz',present:'Presente',paused:'En pausa',not_started:'Aún no estaba en la lista'};
function attendancePanel(full=false){
 const all=radarRows(),eligible=all.filter(m=>!['paused','not_started'].includes(m.state)),missing=eligible.filter(m=>['never','missing','away'].includes(m.state)),lurkers=eligible.filter(m=>m.state==='lurker'),rows=full?all:all.slice(0,6);
 return `<section class="attendance-section wide-section"><div class="section-heading"><div><div class="eyebrow">CONTROL DE ASISTENCIA / EL RADAR DEL SOTA</div><h2 class="section-title" style="margin-top:9px">Los que brillan por su ausencia</h2></div><div class="button-row">${remote?'<button class="secondary" id="refresh-server">Actualizar desde Discord ↻</button>':''}<button class="secondary" data-add-member>Agregar integrante ＋</button></div></div>${remote&&mode!=='demo'?'<p class="form-help">El bot agrega automáticamente a los integrantes de Discord, incluso a los desconectados. No hace falta cargarlos a mano.</p>':''}<div class="attendance-stats"><div><strong>${missing.length}</strong><span>SIN APARECER O 7+ DÍAS SIN SEÑAL</span></div><div><strong>${lurkers.length}</strong><span>CONECTADOS SIN ENTRAR A VOZ</span></div><div><strong>${eligible.filter(m=>m.playVoiceDays>0).length}</strong><span>CON JUEGO Y VOZ REGISTRADOS</span></div><div><strong>${all.length}</strong><span>INTEGRANTES EN LA LISTA</span></div></div><div class="panel">${rows.length?`<div class="history-wrap"><table class="attendance-table"><thead><tr><th>INTEGRANTE</th><th>ÚLTIMA SEÑAL</th><th>DÍAS CONECTADO</th><th>DÍAS EN VOZ</th><th>JUEGO + VOZ</th><th>EL VEREDICTO</th></tr></thead><tbody>${rows.map(m=>`<tr><td><button class="member-link" data-member="${esc(m.id)}">${avatar(m.name,m.id)}<strong>${esc(m.name)}</strong><span>↗</span></button></td><td><strong class="absence-gap">${m.gap===null?'Sin registros':m.gap===0?'Hoy':m.gap===1?'Hace 1 día':'Hace '+m.gap+' días'}</strong><small class="absence-date">${m.last?date(m.last,{year:'numeric'}):'En lista desde '+date(m.since,{year:'numeric'})}</small></td><td class="attendance-number">${m.days}</td><td class="attendance-number">${m.voiceDays}</td><td class="attendance-number">${m.playVoiceDays}</td><td><span class="attendance-badge state-${m.state}">${attendanceLabels[m.state]}</span></td></tr>`).join('')}</tbody></table></div>`:empty(remote?'Esperando la lista de Discord':'Todavía no hay integrantes',remote?'Cuando el bot esté conectado, aparecerán automáticamente. Revisá su estado en Datos e integración.':'Usá Agregar integrante para crear tu lista o conectá el bot de Discord.')}${!full&&all.length>6?'<div class="panel-bottom"><button class="link-button" data-view="banda">Ver toda la banda, incluidos los que no aparecieron ↗</button></div>':''}</div><p class="form-help">El radar usa el período y el jugador elegidos; no los filtros de juego o actividad. “No apareció” significa sin registros en ese período. 7+ días es desde la última señal hasta el final del período; “Sin estrenar” es cero registros desde su alta. Juego + voz indica ambos estados, no confirma que compartieran partida. Invisible y cortes del bot pueden dejar huecos.</p></section>`;
}
function openMember(id){
 const m=id?currentMembers().find(m=>m.id===id):null;const f=$('#member-form');f.reset();f.elements.id.value=m?.id||'';f.elements.name.value=m?.name||'';f.elements.discordId.value=m?.id&&!m.id.startsWith('manual-')&&/^\d+$/.test(m.id)?m.id:'';f.elements.discordId.disabled=!!m;f.elements.since.value=localDate(m?.since||new Date()).slice(0,10);f.elements.active.checked=m?m.active:true;$('#member-error').textContent='';$('#member-note').textContent=mode==='demo'?'Estás viendo una muestra. Agregar un integrante abre tu lista real; no copia los nombres ficticios.':'Un integrante sin conexiones sigue en el radar. La fecha de alta indica desde cuándo lo esperás.';f.querySelector('[type=submit]').disabled=!!m&&mode==='demo';$('#member-dialog').showModal();
}
$('#member-form').addEventListener('submit',async e=>{
 e.preventDefault();const f=e.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;
 try{const name=f.elements.name.value.trim(),existing=mergeMembers(members,local).find(m=>m.name.toLocaleLowerCase()===name.toLocaleLowerCase()),id=f.elements.id.value||f.elements.discordId.value.trim()||existing?.id||'manual-'+uuid(),old=members.find(m=>m.id===id),since=new Date(f.elements.since.value+'T00:00:00');if(+since>Date.now())throw Error('La fecha de alta no puede ser futura.');const [m]=validateMembers([{id,name,since:since.toISOString(),active:f.elements.active.checked}]);if(existing&&existing.id!==id)throw Error('Ya hay otro integrante con ese nombre.');if(remote)await request('./api/members/'+encodeURIComponent(id),'PUT',m);members=[...members.filter(x=>x.id!==id),m];mode='real';if(!remote)saveLocal();else persistMode();$('#member-dialog').close();populateFilters();render();toast(old?'Integrante actualizado.':'Integrante agregado. Aparece aunque tenga cero conexiones.')}catch(e){$('#member-error').textContent=e.message}finally{button.disabled=false}
});
function stats(){return `<div class="stat-grid"><div class="stat accent"><div class="stat-label">HORAS DE VICIO <span>↗</span></div><div class="stat-value">${hours(summary.play)}<small>h</small></div><div class="stat-note">${percent(summary.play,summary.total)}% del tiempo con juego registrado</div></div><div class="stat"><div class="stat-label">TIEMPO CONECTADO <span>◷</span></div><div class="stat-value">${hours(summary.total)}<small>h</small></div><div class="stat-note">${plural(summary.sessions,'sesión','sesiones')} en el período</div></div><div class="stat"><div class="stat-label">LA BANDA ACTIVA <span>♧</span></div><div class="stat-value">${summary.players.length}<small>${summary.players.length===1?'jugador':'jugadores'}</small></div><div class="stat-note">${plural(summary.games.length,'juego','juegos')} en la rotación</div></div><div class="stat"><div class="stat-label">HORAS EN VOZ <span>≋</span></div><div class="stat-value">${hours(summary.voice)}<small>h</small></div><div class="stat-note">Estar en voz ≠ estar hablando</div></div></div>`}
function activityChart(){
 const buckets=Array.from({length:7},()=>Object.fromEntries(Object.keys(STATES).map(k=>[k,0])));
 for(const r of selected){let t=+r.clippedStart;while(t<+r.clippedEnd){const d=new Date(t),next=new Date(d);next.setHours(24,0,0,0);const end=Math.min(+next,+r.clippedEnd);buckets[(d.getDay()+6)%7][category(r)]+=(end-t)/60000;t=end}}
 const totals=buckets.map(b=>Object.values(b).reduce((a,b)=>a+b,0)),max=Math.max(...totals,1),peak=totals.indexOf(Math.max(...totals));
 return `<section class="panel"><div class="panel-head"><div><h2 class="section-title">Ritmo de la semana</h2><p>Horas acumuladas por día de la semana</p></div><span class="mini-label">H / PERSONA</span></div><div class="chart-legend"><span><i class="swatch" style="background:#789b32"></i>Juego + voz</span><span><i class="swatch" style="background:#b4ce62"></i>Juego sin voz</span><span><i class="swatch" style="background:#e58c53"></i>Charla</span><span><i class="swatch" style="background:#b5bab3"></i>Otros estados</span></div><div class="panel-body"><div class="chart" role="img" aria-label="Horas por día: ${totals.map((n,i)=>['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][i]+': '+hours(n)).join('; ')}">${buckets.map((b,i)=>`<div class="bar-col"><span class="bar-value">${hours(totals[i])}</span><div class="bar-stack" style="height:${totals[i]/max*118}px" title="${hours(totals[i])} horas">${Object.entries(b).map(([k,m])=>`<span style="height:${totals[i]?m/totals[i]*100:0}%;background:${STATES[k].color}"></span>`).join('')}</div></div>`).join('')}</div><div class="bar-labels">${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map(d=>`<span>${d}</span>`).join('')}</div><div class="chart-foot"><span><i class="dot"></i> ${summary.total?'El pico de la banda':'El archivo espera'}</span><strong>${summary.total?['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][peak]+' · '+hours(totals[peak])+' h':'Todavía sin registros'}</strong></div></div></section>`;
}
function distribution(){let offset=0;const gradient=Object.entries(summary.groups).map(([k,m])=>{const start=offset;offset+=summary.total?m/summary.total*100:0;return `${STATES[k].color} ${start}% ${offset}%`}).join(',');return `<section class="panel"><div class="panel-head"><div><h2 class="section-title">¿A qué vinieron?</h2><p>Una radiografía del tiempo conectado</p></div><span class="mini-label">%</span></div><div class="distribution"><div class="donut" style="background:${summary.total?'conic-gradient('+gradient+')':'#e3e6d9'}" role="img" aria-label="Distribución de actividades"><div class="donut-center">${percent(summary.play,summary.total)}%<small>VINO A JUGAR</small></div></div><div class="distribution-legend">${Object.entries(STATES).map(([k,s])=>`<button data-state="${k}" title="Filtrar: ${s.label}"><i class="swatch" style="background:${s.color}"></i>${s.label}<b>${percent(summary.groups[k],summary.total)}%</b></button>`).join('')}</div></div><div class="panel-bottom">«FANTASMA» = EN VOZ, SIN JUEGO, HABLA MARCADA COMO NO.</div></section>`}
function playerCard(p){const sorted=Object.entries(p.groups).sort((a,b)=>b[1]-a[1]);return `<button class="player-card" data-player-detail="${esc(p.id)}"><div class="player-top">${avatar(p.name,p.id)}<div><div class="player-name">${esc(p.name)}</div><div class="player-sub">${plural(p.sessions.size,'SESIÓN','SESIONES')}</div></div><span class="player-arrow">↗</span></div><div class="player-hours">${hours(p.total)}<small>h conectado</small></div>${microbar(p.groups,p.total)}<div class="player-foot"><span>${STATES[sorted[0][0]].short}</span><span>${percent(p.play,p.total)}% juego</span></div></button>`}
function gamesList(limit=4){return summary.games.length?`<div class="game-list">${summary.games.slice(0,limit).map((g,i)=>`<div class="game-row"><span class="game-rank">${String(i+1).padStart(2,'0')}</span><div class="game-icon">${esc(initials(g.name))}</div><div class="game-info"><strong>${esc(g.name)}</strong><small>${plural(g.players.size,'jugador','jugadores')} · ${plural(g.sessions.size,'sesión','sesiones')}</small></div><div class="game-hours">${hours(g.total)}<small>HORAS</small></div></div>`).join('')}</div>`:empty('Sin juegos por acá','No hay juegos registrados con estos filtros.')}
function heatmap(){const end=new Date(Math.min(+range[1],Date.now())),start=new Date(end);start.setDate(start.getDate()-27);start.setHours(0,0,0,0);const cells=Array.from({length:28},(_,i)=>{const day=new Date(start);day.setDate(day.getDate()+i);return {day,m:dailyMinutes(selected,day)}}),max=Math.max(...cells.map(d=>d.m),1);return `<section class="panel"><div class="panel-head"><div><h2 class="section-title">El pulso del club</h2><p>Últimos 28 días del período · tiempo conectado</p></div><span class="mini-label">28 DÍAS</span></div><div class="panel-body"><div class="heatmap">${Array.from({length:7},(_,i)=>`<span class="heat-label">${weekdays[(start.getDay()+i)%7].toUpperCase()}</span>`).join('')}${cells.map(({day,m})=>`<div class="heat-cell" style="background:${m?['#e3edc1','#cfe19b','#abc76b','#7d9f41'][Math.min(3,Math.ceil(m/max*4)-1)]:'#f0f1e8'}" title="${date(day,{year:'numeric'})}: ${hours(m)} h" aria-label="${date(day)}: ${hours(m)} horas">${day.getDate()}</div>`).join('')}</div><div class="heat-foot"><span>${date(start)} — ${date(end)}</span><span class="heat-key">MENOS ${['#f0f1e8','#e3edc1','#cfe19b','#abc76b','#7d9f41'].map(c=>`<i style="background:${c}"></i>`).join('')} MÁS</span></div></div></section>`}
function empty(title,text,action=false){return `<div class="empty"><div class="empty-icon">✳</div><h3>${title}</h3><p>${text}</p>${action?'<button class="primary" data-add>Registrar la primera sesión ↗</button>':''}</div>`}
function livePanel(){if(mode==='demo'||!remote)return '';const live=remoteState?.live||[];return `<section class="panel wide-section"><div class="panel-head"><h2 class="section-title">Ahora en el club</h2><span class="section-tag">${remoteState?.bot?.connected?'BOT CONECTADO':'OBSERVACIÓN PAUSADA'}</span></div><div class="panel-body">${live.length?`<div class="live-grid">${live.map(r=>`<div class="live-player">${avatar(r.name,r.userId)}<div><strong>${esc(r.name)}</strong><small>${esc(r.game||'Sin juego detectado')} · ${r.inVoice?'En voz':'Fuera de voz'}${r.muted?' · Muteado':''}${r.streaming?' · Transmitiendo':''}</small></div></div>`).join('')}</div>`:'<p class="form-help">'+(remoteState?.bot?.connected?'No hay miembros visibles conectados.':'El bot está desconectado. El historial sigue disponible.')+'</p>'}<p class="form-help">Actualizado cada minuto. Los filtros de historial no afectan esta vista.</p></div></section>`}
function overview(){return attendancePanel()+stats()+livePanel()+`<div class="content-grid">${activityChart()}${distribution()}</div><section class="wide-section"><div class="section-heading"><h2 class="section-title">Los habituales <small>/ TIEMPO CONECTADO</small></h2><button class="link-button" data-view="banda">Toda la banda ↗</button></div>${summary.players.length?`<div class="players-grid">${summary.players.slice(0,4).map(playerCard).join('')}</div>`:`<div class="panel">${empty('La noche está en blanco','Registrá una sesión o ajustá los filtros para ver la actividad.',true)}</div>`}</section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2 class="section-title">En la rotación</h2><button class="link-button" data-view="juegos">Ver juegos ↗</button></div>${gamesList()}</section>${heatmap()}</div><section class="panel wide-section"><div class="panel-head"><h2 class="section-title">Últimas huellas</h2><button class="link-button" data-view="historial">Abrir el archivo ↗</button></div><div style="height:15px"></div>${table([...selected].sort((a,b)=>b.start.localeCompare(a.start)).slice(0,5),false)}</section>`}
function playersView(){return attendancePanel(true)+`<section class="wide-section"><h2 class="section-title" style="margin-bottom:18px">Los que registraron actividad</h2>${summary.players.length?`<div class="players-grid">${summary.players.map(playerCard).join('')}</div>`:empty('Sin actividad registrada','La lista de arriba conserva a todos los integrantes, incluso con cero conexiones.')}</section>`}
function gamesView(){return `<div class="view-intro"><p>El tiempo de cada jugador se suma: 4 amigos jugando una hora = 4 horas-persona.</p><span class="section-tag">${summary.games.length} JUEGOS</span></div>${summary.games.length?`<div class="game-grid">${summary.games.map((g,i)=>`<article class="game-card"><div class="game-icon" style="background:${['#344433','#574735','#3f3d4b','#444c33','#4a4339','#33464b'][i%6]}">${esc(initials(g.name))}</div><span class="mini-label">ROTACIÓN / ${String(i+1).padStart(2,'0')}</span><h3>${esc(g.name)}</h3><span class="recent">${plural(g.sessions.size,'SESIÓN','SESIONES')} · ${plural(g.players.size,'JUGADOR','JUGADORES')}</span><div class="game-total">${hours(g.total)} <small>h de juego</small></div><div class="name-tags">${[...g.players].map(([id,n])=>`<span>${esc(n)}</span>`).join('')}</div><div style="margin-top:20px"><button class="link-button" data-filter-game="${esc(g.name)}">Ver sus registros ↗</button></div></article>`).join('')}</div>`:empty('Nadie abrió un juego','Probá otro período o cargá el nombre del juego en una sesión.')}`}
function table(rows,editable=true){if(!rows.length)return empty('Sin huellas en este período','Cambiá los filtros o sumá el primer registro.',true);return `<div class="history-wrap"><table><thead><tr><th>JUGADOR</th><th>FECHA / HORARIO</th><th>JUEGO</th><th>ACTIVIDAD</th><th>TIEMPO</th>${editable?'<th>ORIGEN / ACCIÓN</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td><div class="member-cell">${avatar(r.name,r.userId)}${esc(r.name)}</div></td><td class="date-cell" title="${esc(r.start)} — ${esc(r.end)}">${date(r.start,{year:'numeric'})}<br>${time(r.start)} → ${date(r.start)===date(r.end)?'':date(r.end)+' '}${time(r.end)}</td><td>${esc(r.game||'—')} ${r.streaming?'<span title="Transmitió">↗</span>':''}</td><td>${stateBadge(r)}${r.muted?'<span title="Muteado"> · M</span>':''}${r.deafened?'<span title="Ensordecido"> · D</span>':''}${r.camera?'<span title="Cámara"> · C</span>':''}</td><td class="date-cell" title="Tiempo dentro del período filtrado">${hours(r.minutes)} h</td>${editable?`<td><div class="table-actions"><span class="mini-label" style="align-self:center;margin-right:6px">${r.source==='demo'?'MUESTRA':r.source.toUpperCase()}</span><button class="icon-button" data-record-detail="${esc(r.id)}" aria-label="Detalle del registro de ${esc(r.name)}">↗</button>${mode!=='demo'&&r.source==='manual'?`<button class="icon-button" data-edit="${esc(r.id)}" aria-label="Editar registro de ${esc(r.name)}">✎</button><button class="icon-button danger" data-delete="${esc(r.id)}" aria-label="Eliminar registro de ${esc(r.name)}">×</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function historyView(){const rows=[...selected].sort((a,b)=>b.start.localeCompare(a.start)),pages=Math.max(1,Math.ceil(rows.length/15));page=Math.min(page,pages);return `<section class="panel wide-section"><div class="table-toolbar"><input class="search" id="history-search" placeholder="Buscar jugador, juego o nota…" aria-label="Buscar en el historial" value="${esc(search)}"><div class="button-row"><button class="secondary" data-export-csv>Exportar vista CSV ↓</button> <button class="secondary" data-import>Importar JSON ↑</button></div></div>${table(rows.slice((page-1)*15,page*15))}<div class="pagination"><span>${plural(rows.length,'tramo','tramos')} · ${plural(summary.sessions,'sesión','sesiones')} · ${hours(summary.total)} h</span><div><button class="icon-button" data-page="${page-1}" ${page===1?'disabled':''} aria-label="Página anterior">←</button>${page} / ${pages}<button class="icon-button" data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Página siguiente">→</button></div></div></section><p class="form-help">Un tramo representa un estado continuo. Una sesión del bot puede contener varios tramos si cambió el juego, el canal o la presencia. Las horas se recortan al período elegido.</p>`}
function settingsView(){return `<section class="panel wide-section"><div class="panel-body"><h3 class="section-title">La lista del radar</h3><p class="form-help">${remote?'El bot reconoce automáticamente a los integrantes de Discord, incluso a los desconectados. Agregar integrante sirve para una carga manual adicional.':'Usá Agregar integrante para crear tu lista manual, incluidos los que todavía no se conectaron.'} En pausa conserva el historial y lo excluye de los avisos de ausencia.</p><button class="primary" data-add-member>Agregar integrante ＋</button> <button class="secondary" data-view="banda">Ver y editar la banda ↗</button></div></section>${localBackup?'<section class="panel wide-section"><div class="panel-body"><h3 class="section-title">Tu historial local sigue guardado</h3><p class="form-help">El tablero muestra Discord. Descargá los datos anteriores de este navegador y, si querés sumarlos al servidor, importá ese archivo con tu clave de administración.</p><button class="primary" data-export-local>Descargar respaldo local pendiente ↓</button></div></section>':''}<div class="settings-grid"><section class="panel"><div class="panel-body"><span class="setting-status">${remote?'● SERVIDOR DISPONIBLE':'○ MODO LOCAL DISPONIBLE'}</span><h3>El archivo es tuyo.</h3><p>${remote?'Los registros reales se consultan en el servidor. Las operaciones de escritura necesitan tu clave de administración.':'Tus registros reales se guardan en este navegador. No se comparten automáticamente entre PCs ni se conservan si borrás los datos del sitio. El respaldo JSON guarda el historial completo.'}</p><div class="button-row"><button class="primary" data-export-json>Respaldar todo ↓</button><button class="secondary" data-import>Importar respaldo ↑</button></div><p style="margin-top:15px">La muestra está separada de tus datos. El respaldo exporta el conjunto que estés viendo: ${mode==='demo'?'muestra ficticia':'datos reales'}.</p></div></section><section class="panel"><div class="panel-body"><span class="setting-status">${remoteState?.bot?.connected?'● BOT CONECTADO':'○ BOT SIN CONEXIÓN'}</span><h3>Un cronista en Discord.</h3><p>El bot incluido registra presencia, juego detectado, canal de voz, mute, sordera, cámara y transmisión. No escucha ni graba audio. El dato de habla queda desconocido; podés anotarlo manualmente desde el detalle del registro.</p><p>${remoteState?.bot?.lastSeen?'Última señal: '+esc(new Date(remoteState.bot.lastSeen).toLocaleString('es-AR'))+'.':'La versión estática funciona con carga manual. Para automatizar, ejecutá el backend y el bot en Render o en tu PC; las instrucciones están en el proyecto.'}</p>${remote?`<div class="form-token"><label>Clave de administración<input type="password" id="admin-token" autocomplete="off" placeholder="Se conserva solo en esta pestaña"></label><button class="secondary" id="save-token">Guardar clave</button></div>`:''}</div></section><section class="panel"><div class="panel-body"><h3>El diccionario del club.</h3>${Object.entries(STATES).map(([k,s])=>`<dl class="definition"><dt><i class="swatch" style="background:${s.color}"></i> ${s.label}</dt><dd>${{squad:'Tiene un juego registrado y está en un canal de voz.',solo:'Tiene juego registrado y no está en voz.',chat:'Está en voz, sin juego registrado y con habla marcada como «sí».',ghost:'Está en voz, sin juego registrado y con habla marcada como «no».',quiet:'Está en voz, sin juego registrado y no sabemos si habló.',lobby:'Está conectado, sin juego registrado y fuera de voz.'}[k]}</dd></dl>`).join('')}<div class="local-note">Un juego no detectado no prueba que no esté jugando. Invisible aparece como desconectado para el bot. Ausente y No molestar son estados de presencia; no describen actividad real.</div></div></section><section class="panel"><div class="panel-body"><h3>Cómo leer los números.</h3><p>Las horas son horas-persona, no duración de la partida grupal. Los cambios de estado se registran en tramos sin superposición. La sesión se cuenta una vez por conexión aunque tenga varios juegos.</p><p>Podés consultar 7 días, 2 semanas, 1, 3 o 6 meses, un año o fechas propias. No se inventan datos de períodos anteriores: el historial automático empieza cuando se activa el bot.</p><p>La zona horaria es la de tu dispositivo. El archivo guarda fechas UTC. Muteado no significa silencio y estar en voz no significa hablar.</p><div class="button-row"><button class="secondary" id="refresh-server">Actualizar servidor ↻</button></div></div></section></div>`}

function setView(v){if(!titles[v])return;view=v;search='';page=1;const [title,subtitle]=titles[v];$('#page-title').innerHTML=esc(title)+(/[?!.]$/.test(title)?'':'<span>.</span>');$('#page-subtitle').textContent=subtitle;$('#view-label').textContent={resumen:'RESUMEN',banda:'LA BANDA',juegos:'LOS JUEGOS',historial:'HISTORIAL',ajustes:'DATOS E INTEGRACIÓN'}[v];$$('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));for(const s of ['.filterbar','.subfilters'])$(s).hidden=v==='ajustes';$('#advanced-filters').hidden=v==='ajustes'||$('#more-filters').getAttribute('aria-expanded')!=='true';$('#custom-range').hidden=v==='ajustes'||period!=='custom';render();window.scrollTo({top:0,behavior:'instant'})}
function openPlayer(id){const p=summary.players.find(p=>p.id===id);if(!p){openMember(id);return;}const s=summarize(selected.filter(r=>r.userId===id));$('#detail-title').textContent=p.name+' / ficha del club';$('#detail-content').innerHTML=`<p class="dialog-note">${date(range[0],{year:'numeric'})} — ${date(range[1],{year:'numeric'})}. Último tramo: ${date(p.last)} ${time(p.last)}.</p><div class="detail-stats"><div><strong>${hours(p.total)} h</strong>CONECTADO</div><div><strong>${hours(p.play)} h</strong>JUGANDO</div><div><strong>${p.sessions.size}</strong>SESIONES</div></div><div class="detail-list">${Object.entries(p.groups).map(([k,m])=>`<div><span><i class="swatch" style="background:${STATES[k].color}"></i> ${STATES[k].label}</span><strong>${hours(m)} h · ${percent(m,p.total)}%</strong></div>`).join('')}</div><h3 class="section-title">Sus juegos</h3>${s.games.map(g=>`<div class="detail-game"><span>${esc(g.name)}</span><strong>${hours(g.total)} h</strong></div>`).join('')||'<p class="form-help">Sin juegos registrados en este período.</p>'}<div class="dialog-actions"><button class="primary" data-player-history="${esc(p.id)}">Ver historial ↗</button></div>`;$('#detail-dialog').showModal()}
function recordDetail(id){const r=current().find(r=>r.id===id);if(!r)return;$('#detail-title').textContent=r.name+' / registro';$('#detail-content').innerHTML=`<div class="detail-list"><div><span>Actividad</span>${stateBadge(r)}</div>${[['Juego',r.game||'Sin juego registrado'],['Inicio',new Date(r.start).toLocaleString('es-AR')],['Fin',new Date(r.end).toLocaleString('es-AR')],['Presencia',{online:'En línea',idle:'Ausente',dnd:'No molestar',offline:'Desconectado / invisible'}[r.status]],['Voz',r.inVoice?'Sí · '+(r.channel||'Canal sin nombre'):'No'],['Habló',{yes:'Sí (dato manual)',no:'No (dato manual)',unknown:'Desconocido'}[r.spoke]],['Mute / Sordera',(r.muted?'Sí':'No')+' / '+(r.deafened?'Sí':'No')],['Transmisión / Cámara',(r.streaming?'Sí':'No')+' / '+(r.camera?'Sí':'No')],['Origen',r.source]].map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${r.note?`<p class="local-note" style="white-space:pre-wrap">${esc(r.note)}</p>`:''}${remote&&mode!=='demo'&&r.source==='bot'&&r.inVoice?`<div class="local-note">Anotá si habló (dato manual, sin grabación).<div class="button-row" style="margin-top:10px"><button class="secondary" data-speech="yes" data-record-id="${esc(r.id)}">Sí, habló</button> <button class="secondary" data-speech="no" data-record-id="${esc(r.id)}">No habló</button> <button class="secondary" data-speech="unknown" data-record-id="${esc(r.id)}">Desconocido</button></div></div>`:''}`;$('#detail-dialog').showModal()}
function localDate(d){const dt=new Date(d);return new Date(+dt-dt.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function syncVoiceForm(){const f=$('#record-form'),enabled=f.elements.inVoice.value==='true';for(const k of ['spoke','channel','muted','deafened','streaming','camera'])f.elements[k].disabled=!enabled}
function openForm(id){const f=$('#record-form');f.reset();$('#form-error').textContent='';const r=id?local.find(x=>x.id===id):null;f.elements.id.value=r?.id||'';
 $('#form-note').textContent=mode==='demo'?'Este registro iniciará tu historial real. Los datos de muestra no se mezclarán con los tuyos.':'Registrá lo que pasó. Para cambiar de actividad, usá un tramo nuevo.';
 const end=new Date(),start=new Date(+end-60*60000);f.elements.start.value=localDate(r?.start||start);f.elements.end.value=localDate(r?.end||end);
 if(r){for(const k of ['name','game','status','spoke','channel','note'])f.elements[k].value=r[k]??'';f.elements.inVoice.value=String(r.inVoice);for(const k of ['muted','deafened','streaming','camera'])f.elements[k].checked=r[k]}
 syncVoiceForm();$('#record-dialog').showModal();setTimeout(()=>f.elements.name.focus(),50)
}
function adminToken(){try{return sessionStorage.getItem('vicio.admin')||''}catch{return ''}}
async function request(path,method='GET',body){const response=await fetch(path,{method,headers:{'Content-Type':'application/json',...(method==='GET'?{}:{Authorization:'Bearer '+adminToken()})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(12000)});if(!response.ok){let msg;try{msg=(await response.json()).error}catch{}throw Error(msg||(response.status===401?'Guardá la clave de administración en Datos e integración.':'El servidor no pudo completar la operación.'))}return response.json()}
async function refreshServer(silent=false){
 try{
  const d=await request('./api/state');
  if(d.version!==1||!Array.isArray(d.records))throw Error('No hay un backend VICIO en esta dirección.');
  const records=validateImport(d),roster=validateMembers(d.members||[]);
  if(!remote&&(local.length||members.length))localBackup={version:1,dataset:'real',records:local,members:mergeMembers(members,local)};
  remote=true;remoteState=d;local=records;members=roster;
  populateFilters();render();
  if(!silent)toast('Lista e historial de Discord actualizados.');
  return true;
 }catch(e){
  if(remote){remoteState={...remoteState,live:[],bot:{...remoteState?.bot,connected:false}};render()}
  if(!silent)toast('Sin conexión con el backend. El modo local sigue disponible.');
  return false;
 }
}
$('#record-form').addEventListener('submit',async e=>{
 e.preventDefault();const f=e.currentTarget,submit=f.querySelector('[type=submit]');submit.disabled=true;
 try{const data=new FormData(f),name=String(data.get('name')).trim(),existing=mergeMembers(members,local).find(x=>x.name.toLocaleLowerCase()===name.toLocaleLowerCase()),id=data.get('id')||uuid();const r=validateRecord({id,userId:local.find(x=>x.id===id)?.userId||existing?.id||'manual-'+uuid(),name,game:String(data.get('game')||'').trim()||null,start:new Date(String(data.get('start'))).toISOString(),end:new Date(String(data.get('end'))).toISOString(),status:data.get('status'),inVoice:data.get('inVoice')==='true',spoke:data.get('spoke')||'unknown',channel:String(data.get('channel')||''),note:String(data.get('note')||''),muted:data.has('muted'),deafened:data.has('deafened'),streaming:data.has('streaming'),camera:data.has('camera'),source:'manual',sessionId:local.find(x=>x.id===id)?.sessionId||id});
  const next=[...local.filter(x=>x.id!==id),r];assertNoOverlap(next);
  if(remote){await request('./api/records/'+encodeURIComponent(id),'PUT',r);local=next;mode='real';persistMode()}else{local=next;mode='real';saveLocal()}
  $('#record-dialog').close();populateFilters();render();toast(storageOK||remote?'Registro guardado. Ya es parte de la historia.':'Registro disponible en esta pestaña. Exportá un respaldo.');
 }catch(e){$('#form-error').textContent=e.message}finally{submit.disabled=false}
});
$('#record-form').elements.inVoice.addEventListener('change',syncVoiceForm);
async function removeRecord(id){const r=local.find(x=>x.id===id);if(!r||r.source!=='manual')return;if(!confirm(`¿Eliminar el registro de ${r.name} del ${date(r.start)} a las ${time(r.start)}?`))return;try{if(remote)await request('./api/records/'+encodeURIComponent(id),'DELETE');local=local.filter(x=>x.id!==id);if(!remote)saveLocal();populateFilters();render();toast('Registro eliminado.')}catch(e){toast(e.message)}}
function download(content,filename,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJSON(){download(JSON.stringify({version:1,exportedAt:new Date().toISOString(),dataset:mode==='demo'?'demo':'real',records:current(),members:currentMembers()},null,2),'vicio-respaldo-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('Respaldo completo exportado. No depende de los filtros.')}
function csvValue(v){let s=String(v??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCSV(){const header=['Jugador','Inicio UTC','Fin UTC','Juego','Actividad','Horas en período','Presencia','Canal','Habló','Muteado','Ensordecido','Transmitió','Cámara','Origen','Nota'];const rows=selected.map(r=>[r.name,r.start,r.end,r.game||'',STATES[category(r)].label,(r.minutes/60).toFixed(3),r.status,r.channel,r.spoke,r.muted,r.deafened,r.streaming,r.camera,r.source,r.note]);download('\uFEFF'+[header,...rows].map(row=>row.map(csvValue).join(';')).join('\r\n'),'vicio-vista-'+new Date().toISOString().slice(0,10)+'.csv','text/csv;charset=utf-8');toast('Vista filtrada exportada en CSV.')}
$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>40*1024*1024)throw Error('El respaldo supera 40 MB.');const payload=JSON.parse(await f.text()),records=validateImport(payload);if(payload.dataset==='demo'||records.some(r=>r.source==='demo'))throw Error('Este archivo es una muestra ficticia. No se importa al historial real.');const merged=new Map(local.map(r=>[r.id,r]));let added=0;for(const r of records){if(merged.has(r.id)){if(JSON.stringify(merged.get(r.id))!==JSON.stringify(r))throw Error('Hay registros con el mismo ID y contenido distinto. No se importó el archivo.')}else{merged.set(r.id,r);added++}}
 const importedMembers=validateMembers(payload.members||[]),nextMembers=new Map(members.map(m=>[m.id,m]));for(const m of importedMembers)if(!nextMembers.has(m.id))nextMembers.set(m.id,m);const next=[...merged.values()];assertNoOverlap(next);if(next.length>100000)throw Error('Se superó el límite de 100.000 tramos.');if(remote)await request('./api/import','POST',{version:1,records,members:importedMembers});local=next;members=[...nextMembers.values()];mode='real';if(!remote)saveLocal();else persistMode();populateFilters();render();toast(`${added} registros importados. Se omitieron los duplicados idénticos.`)}catch(e){toast('No se importó: '+e.message)}finally{e.target.value=''}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-add-member')){openMember();return}
 if(b.dataset.member){openMember(b.dataset.member);return}
 if(b.dataset.view){setView(b.dataset.view);return}
 if(b.hasAttribute('data-add')||b.id==='add-record'){openForm();return}
 if(b.classList.contains('close-dialog')){b.closest('dialog').close();return}
 if(b.dataset.period){if(b.dataset.period==='custom'){$('#custom-range').hidden=false;period='custom';if(!$('#range-start').value){$('#range-start').value=localDate(new Date(Date.now()-30*86400000)).slice(0,10);$('#range-end').value=localDate(new Date()).slice(0,10)}}else{period=b.dataset.period;$('#custom-range').hidden=true}$$('[data-period]').forEach(x=>x.classList.toggle('active',x===b));page=1;render();return}
 if(b.dataset.playerDetail){openPlayer(b.dataset.playerDetail);return}
 if(b.dataset.recordDetail){recordDetail(b.dataset.recordDetail);return}
 if(b.dataset.speech){void (async()=>{try{const result=await request('./api/records/'+encodeURIComponent(b.dataset.recordId)+'/speech','PATCH',{spoke:b.dataset.speech});local=local.map(r=>r.id===result.record.id?validateRecord(result.record):r);render();$('#detail-dialog').close();recordDetail(result.record.id);toast('Dato de habla actualizado.')}catch(e){toast(e.message)}})();return}
 if(b.dataset.edit){openForm(b.dataset.edit);return}
 if(b.dataset.delete){void removeRecord(b.dataset.delete);return}
 if(b.dataset.page){page=Number(b.dataset.page);render();return}
 if(b.dataset.state){$('#state-filter').value=b.dataset.state;page=1;render();return}
 if(b.dataset.filterGame){$('#game-filter').value=b.dataset.filterGame;setView('historial');return}
 if(b.dataset.playerHistory){$('#detail-dialog').close();$('#player-filter').value=b.dataset.playerHistory;setView('historial');return}
 if(b.hasAttribute('data-export-local')){if(localBackup)download(JSON.stringify(localBackup,null,2),'vicio-respaldo-local-pendiente.json','application/json');return}
 if(b.hasAttribute('data-export-json')){exportJSON();return}
 if(b.hasAttribute('data-export-csv')){exportCSV();return}
 if(b.hasAttribute('data-import')){$('#import-file').click();return}
 if(b.id==='toggle-data'){mode=mode==='demo'?'real':'demo';persistMode();search='';page=1;populateFilters();render();return}
 if(b.id==='more-filters'){const open=$('#advanced-filters').hidden;$('#advanced-filters').hidden=!open;b.setAttribute('aria-expanded',String(open));b.textContent=open?'Menos filtros −':'Más filtros ＋';return}
 if(b.id==='reset-filters'){for(const s of ['#player-filter','#game-filter','#state-filter'])$(s).value='';$$('[data-extra]').forEach(x=>x.value='');search='';page=1;render();return}
 if(b.id==='apply-range'){const start=$('#range-start').value,end=$('#range-end').value;if(!start||!end||start>end){toast('Elegí una fecha inicial y final válidas.');return}period='custom';render();return}
 if(b.id==='refresh-server'){void refreshServer();return}
 if(b.id==='save-token'){try{sessionStorage.setItem('vicio.admin',$('#admin-token').value);$('#admin-token').value='';toast('Clave guardada para esta pestaña.')}catch{toast('No se pudo guardar la clave en esta pestaña.')}return}
});
for(const el of [...$$('[data-extra]'),...['#player-filter','#game-filter','#state-filter'].map(s=>$(s))])el.addEventListener('change',()=>{page=1;render()});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='history-search'){const value=e.target.value,caret=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{search=value;page=1;render();const input=$('#history-search');if(input){input.focus();input.setSelectionRange(caret,caret)}},180)}});
for(const d of $$('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
populateFilters();setView('resumen');void refreshServer(true);setInterval(()=>{if(!$('dialog[open]'))void refreshServer(true)},60000);
